
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_absp2_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_absp2", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.892312731380859e+00, -4.728771044817012e+00, -3.143076429891757e+00, -1.032402043603485e+00, 1.683634947902188e+00, 5.012737095052852e+00, 8.814216796359482e+00, 1.270657350440006e+01, 1.592908700322851e+01, 1.672445942892752e+01, 1.020678556196094e+01, 2.842263392624909e-01, -3.123909811212603e-01, 1.926714361117143e-01, 5.571495227145934e-01, 6.938418407296086e-01, 6.944023818873726e-01, 6.468726001030981e-01, 6.034336093294694e-01, 5.743483767429038e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


